  // object-key and choice ordering.
  const canonicalOrder = (order) => {
    const choices = order.choices.map((choice) => {
      const items = Object.entries(choice.items).sort(([a], [b]) => asciiCompare(a, b));
      return [choice.id, items];
    }).sort((a, b) => asciiCompare(JSON.stringify(a), JSON.stringify(b)));
    return JSON.stringify([order.value, order.group, choices]);
  };

  const byId = new Map();
  for (const order of orders) {
    const signature = canonicalOrder(order);
    const previous = byId.get(order.id);
    if (previous) {
      if (previous.signature !== signature) {
        throw new Error(`conflicting definitions for order ${order.id}`);
      }
    } else {
      byId.set(order.id, { order, signature });
    }
  }

  const candidates = [];
  for (const { order } of byId.values()) {
    if (blockedOrders.has(order.id)) continue;
    const choices = order.choices.map((choice) => ({
      id: choice.id,
      quantities: skuKeys.map((sku) => choice.items[sku] ?? 0),
    }));
    candidates.push({ id: order.id, value: order.value, group: order.group, choices });
  }
  // Processing in output order means all stored pair arrays are already sorted.
  candidates.sort((a, b) => asciiCompare(a.id, b.id));

