    if (a.value !== b.value) return a.value > b.value;
    if (a.count !== b.count) return a.count > b.count;
    for (let i = 0; i < a.pairs.length; i++) {
      const pairOrder = asciiCompare(a.pairs[i].order_id, b.pairs[i].order_id);
