  assert.throws(() => allocate({ now: 0, on_hand: { s: 2 }, holds: [], orders: [
    { id: 'same', value: 1, group: null, choices: [{ id: 'c', items: { s: 1 } }] },
    { id: 'same', value: 2, group: null, choices: [{ id: 'c', items: { s: 1 } }] },
  ] }), Error);
